import{_ as t,l as i,o as e,c as s,v as r,p as l,x as n,d,i as c,S as h}from"./chunks/framework.InCnrqk-.js";const m=JSON.parse('{"title":"CSPRNG","description":"","frontmatter":{"title":"CSPRNG","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/csprng.md","filePath":"cs/csprng.md","lastUpdated":1789023840000}'),p={name:"cs/csprng.md"};function P(S,a,_,E,u,A){const o=i("Mermaid");return e(),s("div",null,[a[1]||(a[1]=r('<h1 id="csprng" tabindex="-1">CSPRNG <a class="header-anchor" href="#csprng" aria-label="Permalink to &quot;CSPRNG&quot;">​</a></h1><div class="epigraph"><p>密码学伪随机不是 `rand()`：要前向保密式的状态演化、要抗回溯、熵源要估价。nonce、OAEP 种子、ECDSA 的 $k$、密钥本身，都从这里出来。</p><footer>—— NIST SP 800-90A；对照 Ferguson, Schneier and Kohno 对生成器失败；Katz and Lindell 的 PRG 合同</footer></div><h2 id="定位" tabindex="-1">定位 <a class="header-anchor" href="#定位" aria-label="Permalink to &quot;定位&quot;">​</a></h2><p>上一课<a href="/cs/ecdsa-eddsa">ECDSA / EdDSA</a>把确定性签名当成对 RNG 失败的修复。缺口是<strong>其余一切仍要生成器</strong>：密钥、nonce、盐。PRG 课给了理论 \\(G(s)\\)；本课给操作系统与协议里的 CSPRNG 合同。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>理论 PRG 假设种子均匀保密。实践：熵从中断、抖动、硬件指令来，估计不足会出弱密钥。生成器状态泄漏后，若不能前向安全演化，过去输出可被回溯。缺口是 CSPRNG 的再播种与预测抗性，不是再定义不可区分游戏。</p><h3 id="不要用哈希时间戳当密钥" tabindex="-1">不要用哈希时间戳当密钥 <a class="header-anchor" href="#不要用哈希时间戳当密钥" aria-label="Permalink to &quot;不要用哈希时间戳当密钥&quot;">​</a></h3><p>可预测输入不是熵。Debian OpenSSL 一类事故是种子空间塌缩——点名失败模式，不给复现。</p><p><span class="marginnote">SP 800-90A 的 Hash_DRBG / HMAC_DRBG / CTR_DRBG。Linux getrandom / 用户态 ChaCha。Fork 后要重种。本课不写如何削弱某生成器。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>分层：硬件熵 → 内核混合池 → 用户态 DRBG。列出消费者：密钥、nonce、盐、OAEP 种子。Ed25519 仍依赖 CSPRNG 生成私钥本身。</p>',12)),(e(),l(h,null,{default:n(()=>[c(o,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20ENT%5B%22%E7%86%B5%E6%BA%90%22%5D%20--%3E%20POOL%5B%22%E6%B7%B7%E5%90%88%E6%B1%A0%22%5D%0A%20%20POOL%20--%3E%20DRBG%5B%22CSPRNG%20%E7%8A%B6%E6%80%81%22%5D%0A%20%20DRBG%20--%3E%20OUT%5B%22%E5%AF%86%E9%92%A5%20%2F%20nonce%20%2F%20%E7%9B%90%22%5D%0A%20%20DRBG%20--%3E%20FS%5B%22%E5%89%8D%E5%90%91%E6%BC%94%E5%8C%96%E9%98%B2%E5%9B%9E%E6%BA%AF%22%5D%0A"})]),fallback:n(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<p>图中节点是本课的机制骨架；课程不把图展开成可运行的攻击步骤。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>计算安全处处假设「随机带」。CSPRNG 是这条带的工程实现。失败表现为可预测 nonce（回到误用课）或可预测 \\(k\\)（回到 ECDSA）。HKDF 下一课是从已有秘密派生，不是从熵池抽——二者分工。</p><p>前提写进合同之后，游戏外的误用只当失败模式点名，不在本课写成操作程序。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不评估具体 CPU 指令的熵质量论文全文。下一课 HKDF：已有 IKM 时如何拉出多把键，而不是再去碰熵池。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>签名确定性不取消密钥生成对 CSPRNG 的需求。</li><li>要抗预测与回溯；熵估计失败是规格事故。</li><li><code>rand()</code> 与时间戳不是 CSPRNG。</li><li>下一课 HKDF：从已有秘密派生键。</li><li>出处：NIST SP 800-90A；Ferguson, Schneier and Kohno；对照 RFC 4086。</li></ul>',8))])}const B=t(p,[["render",P]]);export{m as __pageData,B as default};
